import type { SatRecords, SatSource } from "./sat-records";

/**
 * The SAT documents in `docs/sat-md`, generated by `sat-knowledge.ts`: the Anexo 20 and Pagos 2.0
 * guides, the error matrix and the catalogs. `corpus.ts` splits the guides into search passages
 * with `sections.ts`.
 */
export type SatDocumentMetadata = {
  readonly slug: string;
  /** Labels a guide's preamble section, so it is part of that passage's key: never change it. */
  readonly title: string;
  /** The SAT file it comes from, a key of `docs/sat-md/sources.json`. */
  readonly sourceId: keyof SatSourceManifest;
  /** Its file name in `docs/sat-md`. */
  readonly file: string;
};

export type SatDocument = Omit<SatDocumentMetadata, "sourceId" | "file"> & {
  readonly markdown: string;
  /** The SAT file's URL. */
  readonly source: string;
  /** The date the SAT published that file. */
  readonly publishedAt: string | null;
};

/** `docs/sat-md/sources.json`: each SAT file, its hash, and the files generated from it. */
export type SatSourceManifest = Readonly<
  Record<"anexo20" | "pagos" | "matrix" | "catalogs", SatSource>
>;

/**
 * The SAT Markdown without its table padding: cells padded to hundreds of spaces left a search
 * passage mostly blank. Lines stay as they were, so line numbers still match the source.
 */
export function compactSatMarkdown(markdown: string) {
  return markdown
    .split("\n")
    .map((line) => line.replaceAll(/ {2,}/gu, " ").replaceAll(/-{4,}/gu, "---"))
    .join("\n");
}

export const SAT_DOCUMENTS: readonly SatDocumentMetadata[] = [
  {
    slug: "anexo-20-guia-de-llenado-cfdi",
    title: "Anexo 20: CFDI 4.0 filling guide",
    sourceId: "anexo20",
    file: "anexo-20-guia-de-llenado-cfdi.md",
  },
  {
    slug: "complemento-pagos-guia-de-llenado",
    title: "Payment complement (REP, Pagos 2.0) filling guide",
    sourceId: "pagos",
    file: "complemento-pagos-guia-de-llenado.md",
  },
  {
    slug: "matriz-de-errores-cfdi-4-0",
    title: "CFDI 4.0 error matrix (CFDI40xxx)",
    sourceId: "matrix",
    file: "matriz-de-errores-cfdi-4.0.md",
  },
  {
    slug: "catalogos-cfdi-4-0",
    title: "CFDI 4.0 catalogs (catCFDI)",
    sourceId: "catalogs",
    file: "catalogos-cfdi-4.0.md",
  },
];

/** The documents as read from disk, with the matrix and catalogs as records. */
export type SatLibrary = {
  readonly documents: readonly SatDocument[];
  readonly records: SatRecords;
};

/** The library from `docs/sat-md`'s files. */
export function buildSatLibrary(input: {
  readonly markdown: (file: string) => string | undefined;
  readonly sources: SatSourceManifest;
  readonly records: SatRecords;
}): SatLibrary {
  return {
    documents: SAT_DOCUMENTS.map(({ sourceId, file, ...metadata }) => {
      const markdown = input.markdown(file);
      if (!markdown) throw new Error(`SAT document ${file} is not available`);
      const source = input.sources[sourceId];
      return {
        ...metadata,
        markdown: compactSatMarkdown(markdown),
        source: source.url,
        publishedAt: source.publishedAt,
      };
    }),
    records: input.records,
  };
}
